mapper.select:
SELECT COUNT(*)
FROM tl_meeting_participants
WHERE meetings_id = #{meetingsId}

mapper.update:
UPDATE tl_meeting_participants
SET joined_at = NOW(),
    left_at   = NULL
WHERE meetings_id = #{meetingsId}
  AND user_id     = #{userId}

UPDATE tl_meeting_participants
SET left_at = NOW()
WHERE meetings_id = #{meetingsId}
  AND user_id     = #{userId}

mapper.delete:
DELETE FROM tl_meeting_participants
WHERE meetings_id = #{meetingsId}
  AND user_id     = #{userId}
